// Ymatch — chrome (header + footer) + Lucide-style icons.
// Header uses the warm-paper translucent backdrop; footer is the only dark
// surface besides the SocialProof band. Mobile: nav collapses into a
// drawer, WhatsApp button shrinks to icon-only, phone number hides.

const ic = (paths, props = {}) => (
  <svg width={props.size || 20} height={props.size || 20} viewBox="0 0 24 24" fill="none"
    stroke={props.stroke || "currentColor"} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
    {paths}
  </svg>
);
const Icons = {
  search:   (p) => ic(<><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></>, p),
  pin:      (p) => ic(<><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></>, p),
  home:     (p) => ic(<><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></>, p),
  wrench:   (p) => ic(<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>, p),
  monitor:  (p) => ic(<><rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8M12 17v4"/></>, p),
  arrow:    (p) => ic(<><path d="M5 12h14"/><path d="m12 5 7 7-7 7"/></>, p),
  phone:    (p) => ic(<path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/>, p),
  briefcase:(p) => ic(<><rect x="2" y="7" width="20" height="14" rx="2"/><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/></>, p),
  check:    (p) => ic(<polyline points="20 6 9 17 4 12"/>, p),
  menu:     (p) => ic(<><line x1="3" y1="6"  x2="21" y2="6" /><line x1="3" y1="12" x2="21" y2="12" /><line x1="3" y1="18" x2="21" y2="18" /></>, p),
  x:        (p) => ic(<><line x1="18" y1="6"  x2="6"  y2="18" /><line x1="6"  y1="6"  x2="18" y2="18" /></>, p),
  mail:     (p) => ic(<><rect x="3" y="5" width="18" height="14" rx="2"/><polyline points="3 7 12 13 21 7"/></>, p),
  star:     (p) => <svg width={p?.size||16} height={p?.size||16} viewBox="0 0 24 24" fill={p?.fill||"var(--orange)"}><path d="M12 2l3 6.3 6.9 1-5 4.9 1.2 6.8L12 17.8 5.9 21l1.2-6.8L2 9.3l6.9-1z"/></svg>,
};

function WhatsAppGlyph({ size = 16, color = "#fff" }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill={color}><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347"/></svg>
  );
}

// Track viewport width so the header can collapse on mobile without a
// brittle CSS-only solution. 900px is the chrome breakpoint.
function useIsMobile(breakpoint = 900) {
  const [m, setM] = React.useState(() => typeof window !== "undefined" && window.innerWidth < breakpoint);
  React.useEffect(() => {
    const on = () => setM(window.innerWidth < breakpoint);
    window.addEventListener("resize", on);
    return () => window.removeEventListener("resize", on);
  }, [breakpoint]);
  return m;
}

function SiteHeader() {
  const isMobile = useIsMobile();
  const [open, setOpen] = React.useState(false);
  const [openDrop, setOpenDrop] = React.useState(null);
  const links = [
    { id: "vacatures", label: "Vacatures" },
    { id: "sectoren",  label: "Sectoren",  children: [
      { id: "bouw",     label: "Bouw",     hint: "Timmer, metsel, uitvoer",     vacatures: 34, accent: "var(--orange)" },
      { id: "techniek", label: "Techniek", hint: "Elektro, las, installatie",   vacatures: 47, accent: "var(--green)"  },
      { id: "office",   label: "Office",   hint: "Werkvoorbereiding, planning", vacatures: 17, accent: "var(--blue)"   },
    ] },
    { id: "team",      label: "Ons team"  },
    { id: "werkgever", label: "Werkgever" },
  ];

  React.useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
    return () => { document.body.style.overflow = ""; };
  }, [open]);

  return (
    <header style={{ position: "sticky", top: 0, zIndex: 30, background: "rgba(239,234,224,.86)", backdropFilter: "blur(10px)", borderBottom: "1px solid var(--line)" }}>
      <div style={{
        maxWidth: "1200px", margin: "0 auto",
        padding: isMobile ? "14px 20px" : "16px 40px",
        display: "flex", alignItems: "center", gap: isMobile ? "16px" : "32px",
      }}>
        <a href="#top" style={{ display: "inline-flex" }} onClick={() => setOpen(false)}>
          <img src="data:image/svg+xml;base64," alt="Ymatch" style={{ width: isMobile ? "92px" : "108px", display: "block" }} />
        </a>

        {!isMobile && (
          <nav style={{ display: "flex", gap: "2px", marginLeft: "8px" }}>
            {links.map((l) => l.children ? (
              <div key={l.id}
                onMouseEnter={() => setOpenDrop(l.id)}
                onMouseLeave={() => setOpenDrop(null)}
                style={{ position: "relative" }}>
                <a href={`#${l.id}`} style={{
                  fontFamily: "var(--font-display)", fontSize: "14px", fontWeight: 600,
                  color: openDrop === l.id ? "var(--ink)" : "var(--muted)",
                  background: openDrop === l.id ? "var(--bg-2)" : "transparent",
                  textDecoration: "none",
                  padding: "10px 12px 10px 14px", borderRadius: "var(--r-sm)", transition: "all .14s",
                  display: "inline-flex", alignItems: "center", gap: "6px",
                }}>
                  {l.label}
                  <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ transform: openDrop === l.id ? "rotate(180deg)" : "none", transition: "transform .14s" }}>
                    <polyline points="6 9 12 15 18 9"></polyline>
                  </svg>
                </a>
                {/* Dropdown */}
                <div style={{
                  position: "absolute", top: "100%", left: 0,
                  paddingTop: "8px",
                  opacity: openDrop === l.id ? 1 : 0,
                  pointerEvents: openDrop === l.id ? "auto" : "none",
                  transition: "opacity .14s",
                }}>
                  <div style={{
                    background: "var(--card)", border: "1px solid var(--line)", borderRadius: "var(--r)",
                    boxShadow: "var(--shadow-lg)", padding: "8px", minWidth: "300px",
                    display: "flex", flexDirection: "column", gap: "2px",
                  }}>
                    {l.children.map((c) => (
                      <a key={c.id} href={`#${c.id}`} style={{
                        display: "flex", alignItems: "center", gap: "12px",
                        padding: "10px 12px", borderRadius: "var(--r-sm)",
                        textDecoration: "none", color: "var(--ink)", transition: "background .14s",
                      }}
                      onMouseEnter={(e) => e.currentTarget.style.background = "var(--bg-2)"}
                      onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>
                        <span style={{ width: "10px", height: "10px", borderRadius: "50%", background: c.accent, flexShrink: 0 }} />
                        <span style={{ flex: 1, minWidth: 0 }}>
                          <span style={{ display: "block", fontFamily: "var(--font-display)", fontWeight: 700, fontSize: "14px" }}>{c.label}</span>
                          <span style={{ display: "block", fontSize: "12px", color: "var(--muted)", marginTop: "1px" }}>{c.hint}</span>
                        </span>
                        <span style={{ fontFamily: "var(--font-mono)", fontSize: "10px", fontWeight: 700, letterSpacing: ".05em", color: "var(--subtle)", whiteSpace: "nowrap" }}>
                          {c.vacatures} vac.
                        </span>
                      </a>
                    ))}
                    <div style={{ height: "1px", background: "var(--line)", margin: "4px 8px" }} />
                    <a href="#vacatures" style={{
                      display: "flex", alignItems: "center", justifyContent: "space-between",
                      padding: "10px 12px", borderRadius: "var(--r-sm)",
                      textDecoration: "none", fontFamily: "var(--font-display)", fontWeight: 700, fontSize: "13px", color: "var(--ink)",
                    }}
                    onMouseEnter={(e) => e.currentTarget.style.background = "var(--bg-2)"}
                    onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}>
                      Bekijk alle 98 vacatures
                      <span style={{ color: "var(--orange)" }}>→</span>
                    </a>
                  </div>
                </div>
              </div>
            ) : (
              <a key={l.id} href={`#${l.id}`} style={{
                fontFamily: "var(--font-display)", fontSize: "14px", fontWeight: 600,
                color: "var(--muted)", textDecoration: "none",
                padding: "10px 14px", borderRadius: "var(--r-sm)", transition: "all .14s",
              }}
              onMouseEnter={(e) => { e.currentTarget.style.color = "var(--ink)"; e.currentTarget.style.background = "var(--bg-2)"; }}
              onMouseLeave={(e) => { e.currentTarget.style.color = "var(--muted)"; e.currentTarget.style.background = "transparent"; }}>
                {l.label}
              </a>
            ))}
          </nav>
        )}

        <div style={{ marginLeft: "auto", display: "flex", gap: "10px", alignItems: "center" }}>
          {!isMobile && (
            <a href="tel:+31101234567" style={{ display: "inline-flex", alignItems: "center", gap: "8px", fontFamily: "var(--font-mono)", fontSize: "12px", fontWeight: 700, letterSpacing: ".04em", color: "var(--ink)", textDecoration: "none" }}>
              <Icons.phone size={14} /> 010 123 45 67
            </a>
          )}
          <a href="https://wa.me/31612345678" target="_blank" rel="noopener" style={{
            display: "inline-flex", alignItems: "center", justifyContent: "center", gap: "8px",
            fontFamily: "var(--font-display)", fontWeight: 700, fontSize: "14px",
            color: "#fff", background: "var(--wa)", border: 0, textDecoration: "none",
            padding: isMobile ? "10px 12px" : "10px 16px", borderRadius: "var(--r-sm)", cursor: "pointer",
          }}>
            <WhatsAppGlyph />
            {!isMobile && "WhatsApp"}
          </a>
          {isMobile && (
            <button onClick={() => setOpen(true)} aria-label="Menu openen" style={{
              display: "inline-flex", alignItems: "center", justifyContent: "center",
              width: "44px", height: "44px",
              background: "var(--ink)", color: "#fff", border: 0, borderRadius: "var(--r-sm)", cursor: "pointer",
            }}>
              <Icons.menu stroke="#fff" />
            </button>
          )}
        </div>
      </div>

      {/* Mobile drawer */}
      {isMobile && open && (
        <div style={{ position: "fixed", inset: 0, zIndex: 50, background: "var(--ink)", color: "#fff", display: "flex", flexDirection: "column" }}>
          <div style={{ padding: "14px 20px", display: "flex", alignItems: "center", justifyContent: "space-between", borderBottom: "1px solid rgba(255,255,255,.10)" }}>
            <img src="data:image/svg+xml;base64," alt="Ymatch" style={{ width: "92px" }} />
            <button onClick={() => setOpen(false)} aria-label="Menu sluiten" style={{
              display: "inline-flex", alignItems: "center", justifyContent: "center",
              width: "44px", height: "44px", background: "transparent", color: "#fff", border: "1px solid rgba(255,255,255,.20)", borderRadius: "var(--r-sm)", cursor: "pointer",
            }}>
              <Icons.x stroke="#fff" />
            </button>
          </div>
          <nav style={{ flex: 1, padding: "16px 20px", display: "flex", flexDirection: "column", gap: "4px", overflowY: "auto" }}>
            {links.map((l) => (
              <React.Fragment key={l.id}>
                <a href={`#${l.id}`} onClick={() => setOpen(false)} style={{
                  fontFamily: "var(--font-display)", fontWeight: 700, fontSize: "26px", letterSpacing: "-.025em",
                  color: "#fff", textDecoration: "none", padding: "16px 8px",
                  borderBottom: l.children ? "none" : "1px solid rgba(255,255,255,.08)",
                }}>{l.label}</a>
                {l.children && (
                  <div style={{ paddingLeft: "12px", marginBottom: "8px", borderBottom: "1px solid rgba(255,255,255,.08)", paddingBottom: "8px" }}>
                    {l.children.map((c) => (
                      <a key={c.id} href={`#${c.id}`} onClick={() => setOpen(false)} style={{
                        display: "flex", alignItems: "center", gap: "12px",
                        padding: "10px 8px", textDecoration: "none",
                      }}>
                        <span style={{ width: "8px", height: "8px", borderRadius: "50%", background: c.accent, flexShrink: 0 }} />
                        <span style={{ fontFamily: "var(--font-display)", fontWeight: 600, fontSize: "17px", color: "rgba(255,255,255,.9)" }}>{c.label}</span>
                        <span style={{ marginLeft: "auto", fontFamily: "var(--font-mono)", fontSize: "11px", fontWeight: 700, letterSpacing: ".05em", color: "rgba(255,255,255,.45)" }}>{c.vacatures} vac.</span>
                      </a>
                    ))}
                  </div>
                )}
              </React.Fragment>
            ))}
          </nav>
          <div style={{ padding: "20px", borderTop: "1px solid rgba(255,255,255,.10)", display: "flex", flexDirection: "column", gap: "10px" }}>
            <a href="tel:+31101234567" style={{
              display: "inline-flex", alignItems: "center", justifyContent: "center", gap: "10px",
              fontFamily: "var(--font-display)", fontWeight: 700, fontSize: "16px",
              color: "var(--ink)", background: "#fff", textDecoration: "none",
              padding: "16px 20px", borderRadius: "var(--r-sm)",
            }}>
              <Icons.phone size={18} stroke="var(--ink)" /> 010 123 45 67
            </a>
            <a href="https://wa.me/31612345678" target="_blank" rel="noopener" style={{
              display: "inline-flex", alignItems: "center", justifyContent: "center", gap: "10px",
              fontFamily: "var(--font-display)", fontWeight: 700, fontSize: "16px",
              color: "#fff", background: "var(--wa)", textDecoration: "none",
              padding: "16px 20px", borderRadius: "var(--r-sm)",
            }}>
              <WhatsAppGlyph size={18} /> WhatsApp Marieke
            </a>
          </div>
        </div>
      )}
    </header>
  );
}

function SiteFooter() {
  const isMobile = useIsMobile(700);
  const cols = [
    { h: "Sectoren",         items: ["Bouw & afbouw", "Techniek & installatie", "Office & commercie", "ZZP-opdrachten"] },
    { h: "Voor jou",         items: ["Vacaturebank", "Ons team", "Hoe het werkt", "Reviews"] },
    { h: "Voor werkgevers",  items: ["Detachering", "Werving & selectie", "ZZP-bemiddeling", "Tarieven"] },
  ];
  return (
    <footer style={{ background: "var(--ink)", color: "rgba(255,255,255,.7)", position: "relative", overflow: "hidden" }}>
      <div aria-hidden="true" style={{ position: "absolute", inset: 0, backgroundImage: "radial-gradient(circle, rgba(255,255,255,.04) 1px, transparent 1.2px)", backgroundSize: "24px 24px", pointerEvents: "none" }} />
      <div aria-hidden="true" style={{ position: "absolute", top: "-160px", right: "-160px", width: "520px", height: "520px", borderRadius: "50%", border: "1px solid rgba(233,78,27,.18)", pointerEvents: "none" }} />
      <div aria-hidden="true" style={{ position: "absolute", top: "-100px", right: "-100px", width: "360px", height: "360px", borderRadius: "50%", border: "1px solid rgba(233,78,27,.10)", pointerEvents: "none" }} />
      <div style={{ position: "relative", maxWidth: "1200px", margin: "0 auto", padding: isMobile ? "56px 20px 28px" : "80px 40px 32px" }}>
        <div style={{
          display: "grid",
          gridTemplateColumns: isMobile ? "1fr" : "1.4fr 1fr 1fr 1fr",
          gap: isMobile ? "40px" : "48px",
          marginBottom: isMobile ? "40px" : "56px",
        }}>
          <div>
            <img src="data:image/svg+xml;base64," alt="Ymatch" style={{ width: "128px", marginBottom: "20px" }} />
            <p style={{ fontFamily: "var(--font-hand)", fontSize: "32px", color: "var(--orange)", margin: "0 0 20px", lineHeight: 1, transform: "rotate(-1.5deg)", transformOrigin: "left" }}>
              Vakmanschap verbindt.
            </p>
            <div style={{ fontSize: "14px", lineHeight: 1.7 }}>
              Hoofdweg 100<br/>
              2908 LC Capelle aan den IJssel<br/>
              <span style={{ color: "rgba(255,255,255,.45)" }}>KvK 12345678 · BTW NL0001.B.01</span>
            </div>
          </div>
          {cols.map((c) => (
            <div key={c.h}>
              <div style={{ fontFamily: "var(--font-mono)", fontSize: "10px", fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", color: "rgba(255,255,255,.4)", marginBottom: "18px" }}>{c.h}</div>
              {c.items.map((x) => (
                <a key={x} href="#" style={{ display: "block", fontSize: "14px", marginBottom: "10px", color: "rgba(255,255,255,.75)", textDecoration: "none" }}>{x}</a>
              ))}
            </div>
          ))}
        </div>
        <div style={{ borderTop: "1px solid rgba(255,255,255,.10)", paddingTop: "24px", display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: "16px" }}>
          <div style={{ fontFamily: "var(--font-mono)", fontSize: "11px", letterSpacing: ".04em", color: "rgba(255,255,255,.4)" }}>
            © 2026 YMATCH RECRUITMENT &amp; DETACHERING · ROTTERDAM
          </div>
          <div style={{ display: "flex", gap: "24px", fontFamily: "var(--font-mono)", fontSize: "11px", letterSpacing: ".04em", color: "rgba(255,255,255,.45)" }}>
            <a href="#" style={{ color: "inherit", textDecoration: "none" }}>PRIVACY</a>
            <a href="#" style={{ color: "inherit", textDecoration: "none" }}>VOORWAARDEN</a>
            <a href="#" style={{ color: "inherit", textDecoration: "none" }}>COOKIES</a>
          </div>
        </div>
      </div>
    </footer>
  );
}

Object.assign(window, { Icons, WhatsAppGlyph, SiteHeader, SiteFooter, useIsMobile });
